import {
  detectCapabilities,
  parsePrimaryDA,
  probeFromEnv,
  mergeProbeResults,
} from '@tuix/platform'

const fromDa = parsePrimaryDA('\x1b[?62;1;4;6;9;15;22;29c')
const fromEnvProbe = probeFromEnv(process.env)
const probe = mergeProbeResults(fromDa ?? undefined, fromEnvProbe)

const caps = detectCapabilities({
  env: {
    TERM: process.env.TERM,
    COLORTERM: process.env.COLORTERM,
    TERM_PROGRAM: process.env.TERM_PROGRAM,
  },
  probe,
})

