  writeGraphicsLive,
} from '@tuix/platform'

const caps = detectCapabilities({ env: process.env })
const protocol = selectGraphicsProtocol(caps)

const pixels = new Uint8Array(16 * 16 * 3)
const encoded = encodeGraphics(caps, {
  data: pixels,
  width: 16,
  height: 16,
  channels: 3,
  format: 'rgb',
})

if (!encoded.fallback) {
  // encoded.protocol is 'sixel' | 'kitty' | 'iterm2'
  // encoded.payload is the escape sequence string
}

await writeGraphicsLive({
  data: pixels,
  width: 16,
  height: 16,
  channels: 3,
})

import {
  REQUEST_CURSOR_POSITION,
  parseCursorPositionReport,
  accumulateCpr,
} from '@tuix/platform'

// Write REQUEST_CURSOR_POSITION ("\x1b[6n") to the terminal, then parse replies.
const single = parseCursorPositionReport('\x1b[12;40R')
// single => { row: 12, col: 40 }

const multi = accumulateCpr(['\x1b[1', '4;8R'])
// multi => { row: 14, col: 8 }

import {
  BRACKETED_PASTE_START,
  BRACKETED_PASTE_END,
  extractBracketedPaste,
  createPasteAccumulator,
} from '@tuix/core'

const once = extractBracketedPaste(
  `pre${BRACKETED_PASTE_START}hello${BRACKETED_PASTE_END}post`
)
// once.paste === 'hello'

const acc = createPasteAccumulator()
acc.push(BRACKETED_PASTE_START + 'ab')
const pastes = acc.push('cd' + BRACKETED_PASTE_END)
// pastes => ['abcd']

