import { Effect } from 'effect'
import { createHooks, composeHooks, type RuntimeHooks } from '@tuix/runtime'

type Msg = { type: 'tick' } | { type: 'noise' }

const filterHooks: RuntimeHooks<unknown, Msg> = {
  onMessage: (msg) =>
    Effect.succeed(msg.type === 'noise' ? null : msg),
  onSubscription: (_sub) =>
    Effect.sync(() => {
      /* observability-grade registration */
    }),
  onError: (error, context) =>
    Effect.sync(() => console.error(context, error)),
}

const logHooks = createHooks<unknown, Msg>({
  afterUpdate: (_old, model, msg) =>
    Effect.sync(() => console.log(msg, model)),
})

export const hooks = composeHooks(filterHooks, logHooks)

import { Effect } from 'effect'
import { type RuntimeHooks } from '@tuix/runtime'

const hooks: RuntimeHooks = {
  onError: (error, context) =>
    Effect.sync(() => {
      // context is 'render' or 'update' (and related paths)
      console.error(`[mvu ${context}]`, error)
    }),
}

