import {
  compileToComponent,
  detectInteractive,
  extractModel,
  extractStateFromSource,
  runApp,
} from '@tuix/jsx'
import { $state } from '@tuix/reactive'

function Counter() {
  const count = $state(0, 'count')
  return <text>Count: {count()}</text>
}

const interactive = detectInteractive(Counter)
const model = extractModel(Counter, { extractState: true })
const component = compileToComponent(Counter, {
  extractState: true,
  interactive: true,
})

const fromSource = extractStateFromSource(
  "const n = $state(1, 'n')"
)
// fromSource => { n: 1 }

await runApp(Counter, { interactive: true, extractState: true })

import {
  $state,
  $states,
  $derived,
  runUntracked,
  bindMvuPush,
  beginViewHydration,
  endViewHydration,
  registerKeyHandler,
} from '@tuix/reactive'

// Runtime binds push so named $set becomes { type: 'set', key, value }
bindMvuPush((msg) => {
  // forward msg into the MVU message queue
  console.log(msg.type, msg.key, msg.value)
})

const fields = $states({ count: 0, label: 'hi' })
const count = $state(0, 'count')
const doubled = $derived(() => count() * 2)

count.$set(3)
const peek = runUntracked(() => doubled())

beginViewHydration({ count: 3, label: 'hi' })
// paint with hydrated runes
endViewHydration()

const off = registerKeyHandler((key) => {
  if (key === 'q') process.exit(0)
})

import { Effect } from 'effect'
import {
  LiveServices,
  TerminalService,
  detectCapabilities,
  PLATFORM_VERSION,
} from '@tuix/platform'

const caps = detectCapabilities({ env: process.env })

const program = Effect.gen(function* () {
  const term = yield* TerminalService
  yield* term.write(`Tuix ${PLATFORM_VERSION}\n`)
  return caps.colors
})

await Effect.runPromise(program.pipe(Effect.provide(LiveServices)))
